-- Bank transfer: the classic ACID transaction
BEGIN;

  -- Debit source account
  UPDATE accounts
  SET balance = balance - 100
  WHERE id = 1;

  -- Verify the account didn't go negative.
  -- (Better: declare CHECK (balance >= 0) on the table and let the
  --  UPDATE above fail by itself.)
  DO $$
  BEGIN
    IF (SELECT balance FROM accounts WHERE id = 1) < 0 THEN
      RAISE EXCEPTION 'Insufficient funds';
    END IF;
  END $$;

  -- Credit destination account
  UPDATE accounts
  SET balance = balance + 100
  WHERE id = 2;

COMMIT;
-- If any statement raises an error, PostgreSQL marks the transaction
-- as aborted: later statements are rejected and the final COMMIT
-- actually performs a ROLLBACK, leaving both accounts unchanged.

-- Read-modify-write with a row lock (works at Read Committed)
BEGIN;
  SELECT email FROM users WHERE id = 42 FOR UPDATE;
  -- other writers of row 42 (and other FOR UPDATE readers) now wait
  UPDATE users SET email = 'new@example.com' WHERE id = 42;
COMMIT;
